import sqlite3, sys, shutil, itertools
from pathlib import Path

# Setup temp package from civ6lib scripts for placement rules
src_dir = Path('/root/skills/civ6lib/scripts')
tmp_dir = Path('/tmp/civ6lib_pkg')
if tmp_dir.exists():
    shutil.rmtree(tmp_dir)
tmp_dir.mkdir(parents=True)
(tmp_dir/'__init__.py').write_text('')
for name in ['hex_utils.py','placement_rules.py']:
    text = (src_dir/name).read_text()
    if name == 'placement_rules.py':
        text = text.replace('from .hex_utils import', 'from civ6lib_pkg.hex_utils import')
    (tmp_dir/name).write_text(text)

sys.path.insert(0, str(tmp_dir.parent))
from civ6lib_pkg.placement_rules import Tile, DistrictType, PlacementRules, validate_district_count, validate_district_uniqueness
from civ6lib_pkg.hex_utils import hex_distance, get_neighbors

map_path = '/data/maps/e2e_test_case_0.Civ6Map'
conn = sqlite3.connect(map_path)
conn.row_factory = sqlite3.Row
c = conn.cursor()
map_row = c.execute('SELECT * FROM Map LIMIT 1').fetchone()
width, height = map_row['Width'], map_row['Height']
plots = {row['ID']: row for row in c.execute('SELECT * FROM Plots').fetchall()}
features = {row['ID']: row['FeatureType'] for row in c.execute('SELECT * FROM PlotFeatures').fetchall()}
resources = {row['ID']: row['ResourceType'] for row in c.execute('SELECT * FROM PlotResources').fetchall()}
improvements = {row['ID']: row['ImprovementType'] for row in c.execute('SELECT * FROM PlotImprovements').fetchall()}
rivers = {row['ID']: row for row in c.execute('SELECT * FROM PlotRivers').fetchall()}

def terrain_from_type(t):
    if t is None:
        return None
    if 'MOUNTAIN' in t:
        return 'MOUNTAIN'
    if t == 'TERRAIN_COAST':
        return 'COAST'
    if t == 'TERRAIN_OCEAN':
        return 'OCEAN'
    if t == 'TERRAIN_LAKE':
        return 'LAKE'
    if t == 'TERRAIN_GRASS':
        return 'GRASS'
    if t == 'TERRAIN_PLAINS':
        return 'PLAINS'
    if t == 'TERRAIN_DESERT':
        return 'DESERT'
    if t == 'TERRAIN_TUNDRA':
        return 'TUNDRA'
    if t == 'TERRAIN_SNOW':
        return 'SNOW'
    if 'GRASS' in t:
        return 'GRASS'
    if 'PLAINS' in t:
        return 'PLAINS'
    if 'DESERT' in t:
        return 'DESERT'
    if 'TUNDRA' in t:
        return 'TUNDRA'
    if 'SNOW' in t:
        return 'SNOW'
    return t

RESOURCE_TYPE = {}

# Build tiles dict

tiles = {}
for pid, prow in plots.items():
    x = pid % width
    y = pid // width
    terr = terrain_from_type(prow['TerrainType'])
    feat = features.get(pid)
    res = resources.get(pid)
    res_type = RESOURCE_TYPE.get(res)
    imp = improvements.get(pid)
    is_hills = False
    if prow['TerrainType'] and 'HILLS' in prow['TerrainType']:
        is_hills = True
    is_floodplains = feat is not None and 'FLOODPLAINS' in feat
    river_edges = []
    rrow = rivers.get(pid)
    if rrow:
        if rrow['IsNEOfRiver']:
            river_edges.append(1)
        if rrow['IsNWOfRiver']:
            river_edges.append(2)
        if rrow['IsWOfRiver']:
            river_edges.append(3)
    tile = Tile(
        x=x,
        y=y,
        terrain=terr,
        feature=feat,
        is_hills=is_hills,
        is_floodplains=is_floodplains,
        river_edges=river_edges,
        river_names=[],
        resource=res,
        resource_type=res_type,
        improvement=imp,
    )
    tiles[(x, y)] = tile

neighbors = {coord: get_neighbors(coord[0], coord[1]) for coord in tiles}
DESTRUCTIBLE_FEATURES = {"FEATURE_FOREST","FEATURE_JUNGLE","FEATURE_MARSH"}
DISTRICTS_FOR_ADJ = {
    DistrictType.CAMPUS,
    DistrictType.HOLY_SITE,
    DistrictType.THEATER_SQUARE,
    DistrictType.COMMERCIAL_HUB,
    DistrictType.HARBOR,
    DistrictType.INDUSTRIAL_ZONE,
    DistrictType.GOVERNMENT_PLAZA,
    DistrictType.ENTERTAINMENT_COMPLEX,
    DistrictType.WATER_PARK,
    DistrictType.ENCAMPMENT,
    DistrictType.AERODROME,
    DistrictType.PRESERVE,
    DistrictType.DIPLOMATIC_QUARTER,
    DistrictType.CITY_CENTER,
    DistrictType.AQUEDUCT,
    DistrictType.DAM,
    DistrictType.CANAL,
    DistrictType.NEIGHBORHOOD,
    DistrictType.SPACEPORT,
}

def effective_feature(tile, district_type_on_tile):
    if district_type_on_tile is None:
        return tile.feature
    if district_type_on_tile == DistrictType.CITY_CENTER:
        return tile.feature
    if tile.feature in DESTRUCTIBLE_FEATURES:
        return None
    return tile.feature


def adjacency_for(district_type, coord, placements):
    tile = tiles[coord]
    if district_type == DistrictType.CAMPUS:
        geo = reef = mount = jungle = dist = 0
        for n in neighbors[coord]:
            nt = tiles.get(n)
            if not nt:
                continue
            adj = placements.get(n)
            feat = effective_feature(nt, adj)
            if nt.is_mountain:
                mount += 1
            if feat:
                if 'GEOTHERMAL_FISSURE' in feat:
                    geo += 1
                if 'REEF' in feat:
                    reef += 1
                if feat == 'FEATURE_JUNGLE':
                    jungle += 1
            if adj in DISTRICTS_FOR_ADJ:
                dist += 1
        return 2*geo + 2*reef + 1*mount + (jungle//2) + (dist//2)
    if district_type == DistrictType.HOLY_SITE:
        nat = mount = forest = dist = 0
        for n in neighbors[coord]:
            nt = tiles.get(n)
            if not nt:
                continue
            adj = placements.get(n)
            feat = effective_feature(nt, adj)
            if nt.is_mountain:
                mount += 1
            if feat and 'NATURAL_WONDER' in feat:
                nat += 1
            if feat == 'FEATURE_FOREST':
                forest += 1
            if adj in DISTRICTS_FOR_ADJ:
                dist += 1
        return 2*nat + 1*mount + (forest//2) + (dist//2)
    if district_type == DistrictType.THEATER_SQUARE:
        ent = wp = dist = 0
        for n in neighbors[coord]:
            nt = tiles.get(n)
            if not nt:
                continue
            adj = placements.get(n)
            if adj == DistrictType.ENTERTAINMENT_COMPLEX:
                ent += 1
            elif adj == DistrictType.WATER_PARK:
                wp += 1
            if adj in DISTRICTS_FOR_ADJ and adj not in (DistrictType.ENTERTAINMENT_COMPLEX, DistrictType.WATER_PARK):
                dist += 1
        return 2*ent + 2*wp + (dist//2)
    if district_type == DistrictType.COMMERCIAL_HUB:
        dist = 0
        harbor = 0
        for n in neighbors[coord]:
            nt = tiles.get(n)
            if not nt:
                continue
            adj = placements.get(n)
            if adj == DistrictType.HARBOR:
                harbor += 1
            if adj in DISTRICTS_FOR_ADJ and adj != DistrictType.HARBOR:
                dist += 1
        river_bonus = 2 if tile.has_river else 0
        return river_bonus + 2*harbor + (dist//2)
    if district_type == DistrictType.HARBOR:
        dist = 0
        cc = 0
        for n in neighbors[coord]:
            nt = tiles.get(n)
            if not nt:
                continue
            adj = placements.get(n)
            if adj == DistrictType.CITY_CENTER:
                cc += 1
            if adj in DISTRICTS_FOR_ADJ and adj != DistrictType.CITY_CENTER:
                dist += 1
        return 2*cc + (dist//2)
    if district_type == DistrictType.INDUSTRIAL_ZONE:
        infra = 0
        dist = 0
        for n in neighbors[coord]:
            nt = tiles.get(n)
            if not nt:
                continue
            adj = placements.get(n)
            if adj in (DistrictType.AQUEDUCT, DistrictType.DAM, DistrictType.CANAL):
                infra += 1
            if adj in DISTRICTS_FOR_ADJ and adj not in (DistrictType.AQUEDUCT, DistrictType.DAM, DistrictType.CANAL):
                dist += 1
        return 2*infra + (dist//2)
    return 0


def total_adjacency(placements):
    total = 0
    per = {}
    for coord, dt in placements.items():
        if dt == DistrictType.CITY_CENTER:
            continue
        bonus = adjacency_for(dt, coord, placements)
        per[coord] = (dt, bonus)
        total += bonus
    return total, per

# Candidate city centers

def is_valid_city_center(tile: Tile):
    if tile.is_water or tile.is_mountain or tile.is_natural_wonder:
        return False
    return True

city_candidates = [coord for coord, tile in tiles.items() if is_valid_city_center(tile)]

SPECIALTY_TYPES = [
    DistrictType.CAMPUS,
    DistrictType.HOLY_SITE,
    DistrictType.THEATER_SQUARE,
    DistrictType.COMMERCIAL_HUB,
    DistrictType.HARBOR,
    DistrictType.INDUSTRIAL_ZONE,
]

TOP_K = 8

best_total = -1
best_placements = None
best_center = None

for center in city_candidates:
    rules = PlacementRules(tiles, center, population=9)
    candidates = {dt: [] for dt in SPECIALTY_TYPES}
    for coord in tiles:
        if hex_distance(coord[0], coord[1], center[0], center[1]) > 3 or coord == center:
            continue
        for dt in SPECIALTY_TYPES:
            if rules.validate_placement(dt, coord[0], coord[1], {center: DistrictType.CITY_CENTER}).valid:
                candidates[dt].append(coord)
    if sum(1 for dt in SPECIALTY_TYPES if candidates[dt]) < 3:
        continue

    # rank candidates by base adjacency (district with only city center)
    ranked = {}
    base_placements = {center: DistrictType.CITY_CENTER}
    for dt in SPECIALTY_TYPES:
        vals = []
        for coord in candidates[dt]:
            placements = dict(base_placements)
            placements[coord] = dt
            bonus = adjacency_for(dt, coord, placements)
            vals.append((bonus, coord))
        vals.sort(key=lambda x: (-x[0], x[1]))
        ranked[dt] = [coord for _, coord in vals[:TOP_K]]

    for dtypes in itertools.combinations([dt for dt in SPECIALTY_TYPES if ranked[dt]], 3):
        for coords in itertools.product(*(ranked[dt] for dt in dtypes)):
            if len(set(coords)) < 3:
                continue
            placements = {center: DistrictType.CITY_CENTER}
            for dt, coord in zip(dtypes, coords):
                placements[coord] = dt
            ok, _ = validate_district_uniqueness(placements)
            if not ok:
                continue
            ok, _ = validate_district_count(placements, population=9)
            if not ok:
                continue
            total, per = total_adjacency(placements)
            if total > best_total:
                best_total = total
                best_placements = placements
                best_center = center

print('best_total', best_total)
print('best_center', best_center)
print('placements', best_placements)
if best_placements:
    total, per = total_adjacency(best_placements)
    print('total', total)
    print('per', {f"{v[0].name}@{k}": v[1] for k,v in per.items()})
